"""duoforge.python.generated_marks: generated files are marked, and marked files are generated (restructure step 9).

A tracked C, header or Python file whose first lines say it is generated ("GENERATED by <tool>", "Generated by
<tool>") carries linguist-generated in .gitattributes, and a marked C, header or Python file says so in its first
lines. Marked JSON data carries its generator's key: a trace its harness version (tools/reference/ps_trace.js), a
reference battle its conformance payload (tools/reference/trace_to_c.py), the legal pool its generated_by.
"""
import json
import re
import subprocess
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
HEADER = re.compile(r"(GENERATED|Generated) (by|from) [A-Za-z]")
CODE = (".c", ".h", ".py")
JSON_KEYS = {"tests/reference/traces/": "harness", "tests/reference/battles/": "conformance",
             "docs/research/expansion/data/legal_pool.json": "meta"}


def tracked():
    out = subprocess.run(["git", "ls-files", "-z"], cwd=ROOT, capture_output=True, check=True).stdout
    return [p for p in out.decode("utf-8").split("\0") if p]


def marked(paths):
    out = subprocess.run(["git", "check-attr", "-z", "linguist-generated", "--stdin"], cwd=ROOT, input="\0".join(paths),
                         capture_output=True, check=True, text=True).stdout.split("\0")
    return {out[i] for i in range(0, len(out) - 2, 3) if out[i + 2] == "true"}


def head(path, lines=6):
    with open(ROOT / path, encoding="utf-8", errors="replace") as fh:
        return "".join(fh.readline() for _ in range(lines))


class GeneratedMarksTest(unittest.TestCase):
    def test_generated_code_is_marked_and_marked_code_is_generated(self):
        paths = tracked()
        code = [p for p in paths if p.endswith(CODE) and not p.startswith("docs/benchmarks/")]
        generated = {p for p in code if HEADER.search(head(p))}
        tagged = marked(paths)
        self.assertEqual(sorted(generated - tagged), [], "generated but not marked in .gitattributes")
        self.assertEqual(sorted(p for p in tagged if p.endswith(CODE) and p not in generated), [],
                         "marked in .gitattributes but without a generated-by line")

    def test_marked_data_names_its_generator(self):
        tagged = marked(tracked())
        data = sorted(p for p in tagged if not p.endswith(CODE))
        self.assertTrue(data)
        for p in data:
            key = next((k for prefix, k in JSON_KEYS.items() if p.startswith(prefix)), None)
            self.assertIsNotNone(key, "%s is marked but no generator is known for it" % p)
            self.assertTrue(p.endswith(".json"), p)
            with open(ROOT / p, encoding="utf-8") as fh:
                self.assertIn(key, json.load(fh), p)


if __name__ == "__main__":
    unittest.main()
